// Fixed approximate campus coordinates, never device location. Model data, not a campus sensor.
const WEATHER_URL='https://api.open-meteo.com/v1/forecast?latitude=35.19051&longitude=113.26013&current=temperature_2m,weather_code,is_day,cloud_cover,precipitation,wind_speed_10m&timezone=Asia%2FShanghai&timeformat=unixtime';
function weatherKind(code){if([0,1].includes(code))return '晴';if([2,3].includes(code))return '多云';if([45,48].includes(code))return '雾';if([51,53,55,56,57,61,63,65,66,67,80,81,82].includes(code))return '雨';if([71,73,75,77,85,86].includes(code))return '雪';if([95,96,99].includes(code))return '雷雨';return null}
function validWeather(c,now){return !!(c&&Number.isFinite(c.time)&&Number.isFinite(c.temperature_2m)&&weatherKind(c.weather_code)&&[0,1].includes(c.is_day)&&now-c.time*1000<3*3600000&&now-c.time*1000>=-600000)}
const weatherCanvas=document.querySelector('#weatherCanvas'),wc=weatherCanvas.getContext('2d'),weatherBadge=document.querySelector('#weatherBadge'),weatherInfo=document.querySelector('#weatherInfo');let weatherData=null,weatherLoading=false,weatherLastAttempt=0,weatherOff=false;const reducedWeather=matchMedia('(prefers-reduced-motion: reduce)');
function weatherMessage(s){weatherBadge.textContent=s;weatherInfo.textContent=s+'。固定校园近似坐标；Open-Meteo 模型资料，非校园现场观测。每15分钟检查，超过3小时视为陈旧；不申请定位。'}
async function refreshWeather(){if(weatherLoading)return;weatherLoading=true;weatherLastAttempt=Date.now();const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),8000);try{const r=await fetch(WEATHER_URL,{signal:controller.signal});if(!r.ok)throw Error('network');const data=await r.json();if(!validWeather(data.current,Date.now()))throw Error('stale');weatherData=data.current;const stamp=new Date(weatherData.time*1000).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false});weatherMessage('焦作 '+weatherKind(weatherData.weather_code)+' '+Math.round(weatherData.temperature_2m)+'°C · '+stamp+' 北京时间 · 模型')}catch(e){weatherData=null;weatherMessage(e.message==='stale'?'天气资料陈旧或不完整 · 默认画面':'天气未连接 · 默认画面')}finally{clearTimeout(timer);weatherLoading=false}}
document.querySelector('#weatherToggle').onclick=e=>{weatherOff=!weatherOff;e.currentTarget.textContent=weatherOff?'天气效果：关':'天气效果：开';e.currentTarget.setAttribute('aria-pressed',String(!weatherOff))};document.querySelector('#weatherRetry').onclick=refreshWeather;
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&Date.now()-weatherLastAttempt>900000)refreshWeather()});setInterval(()=>{if(!document.hidden)refreshWeather()},900000);
let weatherFrame=0;function drawWeather(t){requestAnimationFrame(drawWeather);if(t-weatherFrame<32)return;weatherFrame=t;const b=view.getBoundingClientRect(),w=Math.round(b.width),h=Math.round(b.height);if(weatherCanvas.width!==w||weatherCanvas.height!==h){weatherCanvas.width=w;weatherCanvas.height=h}wc.clearRect(0,0,w,h);weatherBadge.hidden=scene!=='campus';if(weatherData&&!validWeather(weatherData,Date.now())){weatherData=null;weatherMessage('天气资料已过期 · 默认画面')}if(scene!=='campus'||weatherOff||!weatherData||document.hidden)return;const kind=weatherKind(weatherData.weather_code);wc.fillStyle=weatherData.is_day===0?'rgba(16,30,62,.19)':kind==='晴'?'rgba(255,218,130,.04)':'rgba(83,104,121,.09)';wc.fillRect(0,0,w,h);if(kind==='雾'){wc.fillStyle='rgba(224,233,232,.13)';wc.fillRect(0,0,w,h)}if(reducedWeather.matches)return;const snow=kind==='雪';if(!snow&&kind!=='雨'&&kind!=='雷雨')return;const count=snow?40:60;wc.strokeStyle='rgba(191,222,242,.43)';wc.fillStyle='rgba(255,255,255,.75)';wc.lineWidth=1;for(let i=0;i<count;i++){const x=((i*73.37+t*(snow?.008:.04))%w),y=((i*47.91+t*(snow?.025:.31))%h);wc.beginPath();if(snow){wc.arc(x,y,1.6,0,Math.PI*2);wc.fill()}else{wc.moveTo(x,y);wc.lineTo(x-3,y+10);wc.stroke()}}}
weatherMessage('天气连接中 · 默认画面');refreshWeather();requestAnimationFrame(drawWeather);
